			weeks,
			start_date: from.toISOString(),
			end_date: to.toISOString(),
			workout_count: workouts.length,
			total_duration_seconds: totalDurationSeconds,
			exercise_count: exerciseCount,
			set_count: setCount,
			total_volume_kg: totalVolumeKg,
